524	\section{The one-step \'etale plus}
525	
526	\begin{definition}[The refinement equivalence]
527	  \label{def:picEtAffSetoid}
528	  \lean{AlgebraicGeometry.picEtAffSetoid}
529	  \uses{thm:descentMap_congr, def:etale_cover_prod, def:etale_cover_prod_coproj}
530	  \leanok
531	  Consider pairs \((E,\lambda)\) with \(E\) a presented \'etale cover of \(A\) and
532	  \(\lambda \in \mathrm{Desc}(C,E)\). Declare \((E,\lambda) \sim (F,\mu)\) if there exist a
533	  presented \'etale cover \(G\) of \(A\) and homomorphisms of \(A\)-algebras
534	  \(f \colon B_E \to B_G\), \(g \colon B_F \to B_G\) with \(f_{*}\lambda = g_{*}\mu\) in
535	  \(\mathrm{Desc}(C,G)\). This is an equivalence relation.
536	\end{definition}
537	\begin{proof}
538	  \leanok
539	  \uses{lem:descentMap_comp}
540	  \emph{Reflexivity.} \((E,\lambda) \sim (E,\lambda)\) via \(G = E\), \(f = g = \id_{B_E}\).
541	
542	  \emph{Symmetry.} If \((E,\lambda) \sim (F,\mu)\) via \((G,f,g)\), then \((F,\mu) \sim
543	  (E,\lambda)\) via \((G,g,f)\).
544	
545	  \emph{Transitivity.} Suppose \((E,\lambda) \sim (F,\mu)\) via \((G,f,g)\), so \(f_{*}\lambda =
546	  g_{*}\mu\), and \((F,\mu) \sim (H,\nu)\) via \((G',f',g')\), so \(f'_{*}\mu = g'_{*}\nu\). Use
547	  the common refinement \(G \times G'\) with the maps \(\mathrm{inl}_{G,G'} \circ f \colon B_E
548	  \to B_{G \times G'}\) and \(\mathrm{inr}_{G,G'} \circ g' \colon B_H \to B_{G \times G'}\).
549	  Using functoriality of transport (Lemma~\ref{lem:descentMap_comp}) and refinement-map
550	  independence (Theorem~\ref{thm:descentMap_congr}, applied to the two maps
551	  \(\mathrm{inl}_{G,G'} \circ g\) and \(\mathrm{inr}_{G,G'} \circ f'\) out of \(B_F\)),
552	  \[
553	    (\mathrm{inl}_{G,G'} \circ f)_{*}\lambda = \mathrm{inl}_{G,G',*}(f_{*}\lambda) =
554	    \mathrm{inl}_{G,G',*}(g_{*}\mu) = (\mathrm{inl}_{G,G'} \circ g)_{*}\mu
555	  \]
556	  \[
557	    = (\mathrm{inr}_{G,G'} \circ f')_{*}\mu = \mathrm{inr}_{G,G',*}(f'_{*}\mu) =
558	    \mathrm{inr}_{G,G',*}(g'_{*}\nu) = (\mathrm{inr}_{G,G'} \circ g')_{*}\nu,
559	  \]
560	  so \((E,\lambda) \sim (H,\nu)\) via \((G \times G', \mathrm{inl}_{G,G'} \circ f,
561	  \mathrm{inr}_{G,G'} \circ g')\).
562	\end{proof}
563	
564	\begin{definition}[The one-step \'etale plus]
565	  \label{def:PicEtAff}
566	  \lean{AlgebraicGeometry.PicEtAff}
567	  \uses{def:picEtAffSetoid}
568	  \source{kleiman-picard}
569	  \leanok
570	  The set of pairs \((E,\lambda)\) as in Definition~\ref{def:picEtAffSetoid}, modulo the
571	  equivalence relation there, is denoted \(\mathrm{PicEtAff}(C,A)\): the one-step \'etale plus
572	  of the relative Picard functor at \(A\). On affine test schemes this is the \'etale
573	  sheafification of \(\mathrm{relPic}(C,-)\), one plus construction sufficing because that
574	  presheaf is separated for the \'etale topology (established elsewhere).
575	\end{definition}
576	
577	\begin{definition}[The plus class of a descent class]
578	  \label{def:PicEtAff_mk}
579	  \lean{AlgebraicGeometry.PicEtAff.mk}
580	  \uses{def:PicEtAff}
581	  \leanok
582	  For a presented \'etale cover \(E\) of \(A\) and \(\lambda \in \mathrm{Desc}(C,E)\), write
583	  \([E,\lambda] \in \mathrm{PicEtAff}(C,A)\) for the class of the pair \((E,\lambda)\).
584	\end{definition}
585	
586	\begin{lemma}[Every plus class is so represented]
587	  \label{lem:PicEtAff_ind}
588	  \lean{AlgebraicGeometry.PicEtAff.ind}
589	  \uses{def:PicEtAff_mk}
590	  \leanok
591	  Every element of \(\mathrm{PicEtAff}(C,A)\) is of the form \([E,\lambda]\) for some presented
592	  \'etale cover \(E\) of \(A\) and \(\lambda \in \mathrm{Desc}(C,E)\).
593	\end{lemma}
594	\begin{proof}
595	  \leanok
596	  Immediate: \(\mathrm{PicEtAff}(C,A)\) is a quotient of the set of such pairs, and every class
597	  in a quotient is the class of some representative.
598	\end{proof}
599	
600	\begin{theorem}[Equality of plus classes]
601	  \label{thm:PicEtAff_mk_eq_mk_iff}
602	  \lean{AlgebraicGeometry.PicEtAff.mk_eq_mk_iff}
603	  \uses{def:PicEtAff_mk, def:picEtAffSetoid}
604	  \leanok
605	  \([E,\lambda] = [F,\mu]\) in \(\mathrm{PicEtAff}(C,A)\) if and only if there exist a presented
606	  \'etale cover \(G\) of \(A\) and homomorphisms of \(A\)-algebras \(f \colon B_E \to B_G\),
607	  \(g \colon B_F \to B_G\) with \(f_{*}\lambda = g_{*}\mu\).
608	\end{theorem}
609	\begin{proof}
610	  \leanok
611	  This is exactly the defining relation of Definition~\ref{def:picEtAffSetoid}, restated as an
612	  equality of classes in the quotient.
613	\end{proof}
614	
615	\begin{lemma}[Transport to a finer cover preserves the plus class]
616	  \label{lem:PicEtAff_mk_descentMap}
617	  \lean{AlgebraicGeometry.PicEtAff.mk_descentMap}
618	  \uses{thm:PicEtAff_mk_eq_mk_iff, def:descentMap}
619	  \leanok
620	  For \(h \colon B_E \to B_F\) a homomorphism of \(A\)-algebras between carriers of presented
621	  \'etale covers of \(A\) and \(\lambda \in \mathrm{Desc}(C,E)\), \([F, h_{*}\lambda] =
622	  [E,\lambda]\).
623	\end{lemma}
624	\begin{proof}
625	  \leanok
626	  \uses{lem:descentMap_id}
627	  Take \(G = F\) with \(f = \id_{B_F}\) and \(g = h\) in Theorem~\ref{thm:PicEtAff_mk_eq_mk_iff}:
628	  \(f_{*}(h_{*}\lambda) = h_{*}\lambda = g_{*}\lambda\) by Lemma~\ref{lem:descentMap_id}.
629	\end{proof}
