631	\section{The group structure and the unit}
632	
633	\begin{lemma}[Transport through the universal map collapses]
634	  \label{lem:PicEtAff_descentMap_prodLift}
635	  \lean{AlgebraicGeometry.PicEtAff.descentMap_prodLift_inl,
636	    AlgebraicGeometry.PicEtAff.descentMap_prodLift_inr}
637	  \uses{lem:etale_cover_prodLift_comp, lem:descentMap_comp}
638	  \leanok
639	  Let \(E, F, H\) be presented \'etale covers of \(A\), \(f \colon B_E \to B_H\) and
640	  \(g \colon B_F \to B_H\) homomorphisms of \(A\)-algebras, and let
641	  \(\langle f,g\rangle \colon B_{E \times F} \to B_H\) be the induced map of
642	  Definition~\ref{def:etale_cover_prodLift}. Then for \(\lambda \in \mathrm{Desc}(C,E)\) and
643	  \(\mu \in \mathrm{Desc}(C,F)\):
644	  \[
645	    \langle f,g\rangle_{*}(\mathrm{inl}_{E,F,*}\lambda) = f_{*}\lambda, \qquad
646	    \langle f,g\rangle_{*}(\mathrm{inr}_{E,F,*}\mu) = g_{*}\mu.
647	  \]
648	\end{lemma}
649	\begin{proof}
650	  \leanok
651	  By functoriality of transport (Lemma~\ref{lem:descentMap_comp}), the left-hand sides equal
652	  \((\langle f,g\rangle \circ \mathrm{inl}_{E,F})_{*}\lambda\), respectively
653	  \((\langle f,g\rangle \circ \mathrm{inr}_{E,F})_{*}\mu\); by
654	  Lemma~\ref{lem:etale_cover_prodLift_comp}, \(\langle f,g\rangle \circ \mathrm{inl}_{E,F} = f\)
655	  and \(\langle f,g\rangle \circ \mathrm{inr}_{E,F} = g\).
656	\end{proof}
657	
658	\begin{theorem}[Multiplication]
659	  \label{thm:PicEtAff_mk_mul_mk}
660	  \lean{AlgebraicGeometry.PicEtAff.instMul, AlgebraicGeometry.PicEtAff.mk_mul_mk}
661	  \uses{lem:PicEtAff_descentMap_prodLift, thm:PicEtAff_mk_eq_mk_iff, thm:descentMap_congr,
662	    def:etale_cover_prod_coproj}
663	  \leanok
664	  \(\mathrm{PicEtAff}(C,A)\) carries a multiplication, defined on representatives by transport
665	  to a common refinement product cover: for presented \'etale covers \(E, F\) of \(A\) and
666	  \(\lambda \in \mathrm{Desc}(C,E)\), \(\mu \in \mathrm{Desc}(C,F)\),
667	  \[
668	    [E,\lambda] \cdot [F,\mu] = \bigl[\,E \times F,\ \mathrm{inl}_{E,F,*}\lambda \cdot
669	    \mathrm{inr}_{E,F,*}\mu\,\bigr].
670	  \]
671	\end{theorem}
672	\begin{proof}
673	  \leanok
674	  It remains to check that the formula is independent of the chosen representatives, i.e. that
675	  if \((E,\lambda) \sim (E',\lambda')\) via \((H,f,f')\) (so \(f_{*}\lambda = f'_{*}\lambda'\))
676	  and \((F,\mu) \sim (F',\mu')\) via \((G,g,g')\) (so \(g_{*}\mu = g'_{*}\mu'\)), then the two
677	  resulting products agree. Use the common refinement \(H \times G\) of \(E \times F\) and
678	  \(E' \times F'\), with the maps
679	  \(\langle \mathrm{inl}_{H,G} \circ f,\ \mathrm{inr}_{H,G} \circ g\rangle \colon B_{E \times F}
680	  \to B_{H \times G}\) and
681	  \(\langle \mathrm{inl}_{H,G} \circ f',\ \mathrm{inr}_{H,G} \circ g'\rangle \colon
682	  B_{E' \times F'} \to B_{H \times G}\)
683	  (Definition~\ref{def:etale_cover_prodLift}). Since transport is a homomorphism of groups
684	  (Definition~\ref{def:descentMap}), transporting the product
685	  \(\mathrm{inl}_{E,F,*}\lambda \cdot \mathrm{inr}_{E,F,*}\mu\) along the first map yields, by
686	  Lemma~\ref{lem:PicEtAff_descentMap_prodLift} applied twice,
687	  \(\mathrm{inl}_{H,G,*}(f_{*}\lambda) \cdot \mathrm{inr}_{H,G,*}(g_{*}\mu)\); transporting the
688	  primed product along the second map yields
689	  \(\mathrm{inl}_{H,G,*}(f'_{*}\lambda') \cdot \mathrm{inr}_{H,G,*}(g'_{*}\mu')\); these agree
690	  term by term since \(f_{*}\lambda = f'_{*}\lambda'\) and \(g_{*}\mu = g'_{*}\mu'\). Hence the
691	  two products transport to the same class on \(H \times G\), so by
692	  Theorem~\ref{thm:PicEtAff_mk_eq_mk_iff} they define the same element of
693	  \(\mathrm{PicEtAff}(C,A)\).
694	\end{proof}
695	
696	\begin{theorem}[Multiplication of classes on the same cover]
697	  \label{thm:PicEtAff_mk_mul_mk_same}
698	  \lean{AlgebraicGeometry.PicEtAff.mk_mul_mk_same}
699	  \uses{thm:PicEtAff_mk_mul_mk, thm:descentMap_congr, lem:PicEtAff_mk_descentMap}
700	  \leanok
701	  For a presented \'etale cover \(E\) of \(A\) and \(\lambda, \mu \in \mathrm{Desc}(C,E)\),
702	  \([E,\lambda] \cdot [E,\mu] = [E, \lambda \mu]\).
703	\end{theorem}
704	\begin{proof}
705	  \leanok
706	  By Theorem~\ref{thm:PicEtAff_mk_mul_mk}, \([E,\lambda][E,\mu] = [E \times E,
707	  \mathrm{inl}_{E,E,*}\lambda \cdot \mathrm{inr}_{E,E,*}\mu]\). By refinement-map independence
708	  (Theorem~\ref{thm:descentMap_congr}, applied to the two maps \(\mathrm{inr}_{E,E}\) and
709	  \(\mathrm{inl}_{E,E}\) out of \(B_E\)), \(\mathrm{inr}_{E,E,*}\mu = \mathrm{inl}_{E,E,*}\mu\).
710	  Since transport is a homomorphism of groups,
711	  \(\mathrm{inl}_{E,E,*}\lambda \cdot \mathrm{inl}_{E,E,*}\mu = \mathrm{inl}_{E,E,*}(\lambda
712	  \mu)\). Hence \([E,\lambda][E,\mu] = [E \times E, \mathrm{inl}_{E,E,*}(\lambda\mu)] =
713	  [E,\lambda\mu]\), the last equality by Lemma~\ref{lem:PicEtAff_mk_descentMap}.
714	\end{proof}
