716	\begin{definition}[Identity]
717	  \label{def:PicEtAff_one}
718	  \lean{AlgebraicGeometry.PicEtAff.instOne, AlgebraicGeometry.PicEtAff.one_def}
719	  \uses{def:etale_cover_self, def:PicEtAff_mk}
720	  \leanok
721	  The identity element of \(\mathrm{PicEtAff}(C,A)\) is \(1 := [\mathrm{self}(A), 1]\), the
722	  class of the identity descent datum on the trivial cover.
723	\end{definition}
724	
725	\begin{theorem}[The identity is represented on every cover]
726	  \label{thm:PicEtAff_mk_one}
727	  \lean{AlgebraicGeometry.PicEtAff.mk_one}
728	  \uses{def:PicEtAff_one, def:etale_cover_fromSelf, thm:PicEtAff_mk_eq_mk_iff}
729	  \leanok
730	  For every presented \'etale cover \(E\) of \(A\), \([E,1] = 1\) in \(\mathrm{PicEtAff}(C,A)\).
731	\end{theorem}
732	\begin{proof}
733	  \leanok
734	  Apply Theorem~\ref{thm:PicEtAff_mk_eq_mk_iff} with \(G = E\), \(f = \id_{B_E}\), and \(g\)
735	  the canonical map from the trivial cover (Definition~\ref{def:etale_cover_fromSelf}): since
736	  transport is a homomorphism of groups, both \(f_{*}1\) and \(g_{*}1\) equal \(1\), regardless
737	  of \(f\) and \(g\), so they agree.
738	\end{proof}
739	
740	\begin{definition}[Inverse]
741	  \label{def:PicEtAff_inv}
742	  \lean{AlgebraicGeometry.PicEtAff.instInv, AlgebraicGeometry.PicEtAff.mk_inv}
743	  \uses{def:PicEtAff_mk, def:picEtAffSetoid}
744	  \leanok
745	  \(\mathrm{PicEtAff}(C,A)\) carries an inversion, defined on representatives by
746	  \([E,\lambda]^{-1} = [E,\lambda^{-1}]\); well-defined because if \((E,\lambda) \sim (F,\mu)\)
747	  via \((G,f,g)\), so \(f_{*}\lambda = g_{*}\mu\), then applying the group homomorphism
748	  \(f_{*}\), respectively \(g_{*}\), to inverses gives \(f_{*}(\lambda^{-1}) =
749	  (f_{*}\lambda)^{-1} = (g_{*}\mu)^{-1} = g_{*}(\mu^{-1})\), so \((E,\lambda^{-1}) \sim
750	  (F,\mu^{-1})\) via the same \((G,f,g)\).
751	\end{definition}
